package com.vishnu.hotelassistant.service;
import com.vishnu.hotelassistant.entity.Room; import com.vishnu.hotelassistant.repository.RoomRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RoomService {private final RoomRepository repo; public RoomService(RoomRepository repo){this.repo=repo;} public List<Room> all(){return repo.findAll();} public List<Room> available(){return repo.findByAvailableTrue();} public Room create(Room room){return repo.save(room);} public Room update(Long id,Room r){Room x=repo.findById(id).orElseThrow(); x.setType(r.getType());x.setPricePerNight(r.getPricePerNight());x.setAvailable(r.isAvailable());x.setDescription(r.getDescription());x.setImageUrl(r.getImageUrl());return repo.save(x);} public void delete(Long id){repo.deleteById(id);}}
